import sys, threading, http.server, urllib.error, importlib
sys.path.insert(0, '.')
import weather; importlib.reload(weather)
state = {'n': 0, 'fail': 2, 'code': 503}
class H(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        state['n'] += 1
        if state['n'] <= state['fail']:
            self.send_response(state['code']); self.end_headers(); return
        b = b'{"temp": 21}'
        self.send_response(200); self.send_header('Content-Length', str(len(b))); self.end_headers(); self.wfile.write(b)
    def log_message(self, *a): pass
srv = http.server.HTTPServer(('127.0.0.1', 0), H)
threading.Thread(target=srv.serve_forever, daemon=True).start()
sleeps = []
weather.time.sleep = sleeps.append
c = weather.WeatherClient(f'http://127.0.0.1:{srv.server_port}')
print('2x503 then 200:', c.get('Oslo'), 'requests', state['n'], 'sleeps', sleeps)
state.update(n=0, fail=99); sleeps.clear()
try: c.get('Oslo')
except urllib.error.HTTPError as e: print('always 503 ->', e.code, 'requests', state['n'], 'sleeps', sleeps)
state.update(n=0, fail=1, code=500); sleeps.clear()
try: c.get('Oslo')
except urllib.error.HTTPError as e: print('500 ->', e.code, 'requests', state['n'], 'sleeps', sleeps)
srv.shutdown()

